Create custom React hooks for the {{featureName}} feature.

**Your Task**: Create hooks that encapsulate business logic and data operations.

**Hook Patterns**:

### 1. Data Fetching Hook (if dataSource is 'api')

**File**: `src/hooks/use{{featureName}}Data.ts`

```typescript
import { useState, useEffect } from 'react';

interface Use{{featureName}}DataResult<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => void;
}

export function use{{featureName}}Data<T>(
  endpoint: string
): Use{{featureName}}DataResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchData = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err instanceof Error ? err : new Error('Unknown error'));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [endpoint]);

  return { data, loading, error, refetch: fetchData };
}
```

### 2. State Management Hook (if dataSource is 'state')

**File**: `src/hooks/use{{featureName}}State.ts`

```typescript
import { useState, useCallback } from 'react';

interface {{featureName}}State {
  // Define state shape
}

export function use{{featureName}}State() {
  const [state, setState] = useState<{{featureName}}State>({
    // Initial state
  });

  const updateState = useCallback((updates: Partial<{{featureName}}State>) => {
    setState(prev => ({ ...prev, ...updates }));
  }, []);

  const resetState = useCallback(() => {
    setState({
      // Reset to initial state
    });
  }, []);

  return {
    state,
    updateState,
    resetState,
  };
}
```

### 3. Local Storage Hook (if dataSource is 'local-storage')

**File**: `src/hooks/use{{featureName}}Storage.ts`

```typescript
import { useState, useEffect } from 'react';

function getStorageValue<T>(key: string, defaultValue: T): T {
  try {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : defaultValue;
  } catch {
    return defaultValue;
  }
}

export function use{{featureName}}Storage<T>(
  key: string,
  defaultValue: T
) {
  const [value, setValue] = useState<T>(() => 
    getStorageValue(key, defaultValue)
  );

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      console.error('Failed to save to localStorage:', error);
    }
  }, [key, value]);

  return [value, setValue] as const;
}
```

