Integrate the business logic with UI components.

**Your Task**: Update or create components that use the hooks and types.

**Integration Pattern**:

### 1. Container Component (Smart Component)

**File**: `{{componentsDir}}/{{featureName}}/{{featureName}}Container.tsx`

```typescript
import { use{{featureName}} } from '@hooks/use{{featureName}}';
import { {{featureName}}View } from './{{featureName}}View';
import { LoadingSpinner } from '@components/LoadingSpinner';
import { ErrorMessage } from '@components/ErrorMessage';

/**
 * Container component - handles logic and data
 */
export function {{featureName}}Container() {
  const {
    data,
    loading,
    error,
    handleAction,
    refetch,
  } = use{{featureName}}();

  // Handle loading state
  if (loading) {
    return <LoadingSpinner />;
  }

  // Handle error state
  if (error) {
    return (
      <ErrorMessage 
        message={error.message}
        onRetry={refetch}
      />
    );
  }

  // Handle empty state
  if (!data || data.length === 0) {
    return (
      <div>
        <p>No data available</p>
        <button onClick={refetch}>Refresh</button>
      </div>
    );
  }

  // Render view with data
  return (
    <{{featureName}}View
      data={data}
      onAction={handleAction}
    />
  );
}
```

