### 3. Form Component (if needed)

**File**: `{{componentsDir}}/{{featureName}}/{{featureName}}Form.tsx`

```typescript
import { useState, type FormEvent } from 'react';
import type { {{featureName}}FormProps } from '@types/{{featureName}}.types';
import styles from './{{featureName}}Form.module.css';

export function {{featureName}}Form({ 
  initialValues,
  onSubmit,
  onCancel 
}: {{featureName}}FormProps) {
  const [formData, setFormData] = useState(initialValues || {});
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setSubmitting(true);
    setError(null);

    try {
      await onSubmit(formData);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Submission failed');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      {error && <div className={styles.error}>{error}</div>}

      {/* Form fields */}

      <div className={styles.actions}>
        <button type="submit" disabled={submitting}>
          {submitting ? 'Saving...' : 'Save'}
        </button>
        {onCancel && (
          <button type="button" onClick={onCancel}>
            Cancel
          </button>
        )}
      </div>
    </form>
  );
}
```

**Key Integration Principles**:

1. **Container/Presentational Split**:
   - Container = logic, data, hooks
   - Presentational = UI only, props only

2. **Type Everything**:
   - All props interfaces
   - All state variables
   - All event handlers

3. **Handle All States**:
   - Loading
   - Error
   - Empty
   - Success

4. **Extract Reusable Logic**:
   - Move to custom hooks
   - Not in components

