Create integration tests for {{featureName}}.

**Your Task**: Test the complete integration of hooks + components.

**File**: `{{componentsDir}}/{{featureName}}/{{featureName}}.integration.test.tsx`

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { {{featureName}}Container } from './{{featureName}}Container';

// Mock the custom hook
jest.mock('@hooks/use{{featureName}}', () => ({
  use{{featureName}}: jest.fn(),
}));

import { use{{featureName}} } from '@hooks/use{{featureName}}';

const mockUse{{featureName}} = use{{featureName}} as jest.MockedFunction<typeof use{{featureName}}>;

describe('{{featureName}} Integration', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('shows loading state initially', () => {
    mockUse{{featureName}}.mockReturnValue({
      data: null,
      loading: true,
      error: null,
      handleAction: jest.fn(),
      refetch: jest.fn(),
    });

    render(<{{featureName}}Container />);
    expect(screen.getByRole('status')).toBeInTheDocument();
  });

  it('renders data when loaded', async () => {
    const mockData = [
      { id: '1', name: 'Item 1' },
      { id: '2', name: 'Item 2' },
    ];

    mockUse{{featureName}}.mockReturnValue({
      data: mockData,
      loading: false,
      error: null,
      handleAction: jest.fn(),
      refetch: jest.fn(),
    });

    render(<{{featureName}}Container />);

    await waitFor(() => {
      expect(screen.getByText('Item 1')).toBeInTheDocument();
      expect(screen.getByText('Item 2')).toBeInTheDocument();
    });
  });

  it('shows error message when request fails', () => {
    const mockError = new Error('Failed to fetch');

    mockUse{{featureName}}.mockReturnValue({
      data: null,
      loading: false,
      error: mockError,
      handleAction: jest.fn(),
      refetch: jest.fn(),
    });

    render(<{{featureName}}Container />);
    expect(screen.getByText(/failed to fetch/i)).toBeInTheDocument();
  });

  it('calls handleAction when action triggered', async () => {
    const user = userEvent.setup();
    const mockHandleAction = jest.fn();
    const mockData = [{ id: '1', name: 'Item 1' }];

    mockUse{{featureName}}.mockReturnValue({
      data: mockData,
      loading: false,
      error: null,
      handleAction: mockHandleAction,
      refetch: jest.fn(),
    });

    render(<{{featureName}}Container />);

    const actionButton = screen.getByRole('button', { name: /action/i });
    await user.click(actionButton);

    expect(mockHandleAction).toHaveBeenCalledWith(mockData[0]);
  });

  it('refetches data when retry clicked', async () => {
    const user = userEvent.setup();
    const mockRefetch = jest.fn();
    const mockError = new Error('Network error');

    mockUse{{featureName}}.mockReturnValue({
      data: null,
      loading: false,
      error: mockError,
      handleAction: jest.fn(),
      refetch: mockRefetch,
    });

    render(<{{featureName}}Container />);

    const retryButton = screen.getByRole('button', { name: /retry/i });
    await user.click(retryButton);

    expect(mockRefetch).toHaveBeenCalledTimes(1);
  });
});
```

